import {registerTranslations,t} from './i18n.js';
registerTranslations({
  '控制律 / 着陆':'Control laws / landing',
  '抗扰着陆挑战':'Disturbed landing challenge',
  '导出受保护流程原存档':'Export protected original procedure archives',
  '导出当前会话完整研究成果':'Export complete research session',
  '仅本会话 / 未保存':'Session only / unsaved',
  '流程配置':'Procedure configuration','流程结果':'Procedure results','执行日志':'Execution log','待运行配置':'Pending configuration',
  '请求角速度':'Requested angular rate',
  '超调沿目标方向投影。新版主统计来自全部 120 Hz 物理步；20 Hz 曲线及历史抽稀仅供显示。每条结果的 statisticsHz 独立保留。流程完成只表示阶段已执行，稳定与受限情况请看测量。':'Overshoot is projected along the target direction. New primary statistics use all 120 Hz physics steps; 20 Hz and historical decimated curves are for display. Each result preserves its own statisticsHz. Procedure completion only means the stages ran; inspect measured stability and limits.',
  '清空未保存；原记录与当前选择保持不变。':'Clear was not persisted; original records and current selection are unchanged.',
  '浏览器存储不可用':'Browser storage unavailable',
  '浏览器存储不可用；仅本会话 / 未保存':'Browser storage unavailable; session only / unsaved',
  '失败末态仅有诊断快照，没有可恢复的完整终态；可查看 / 导出触发步骤、最后有效状态和输入，不冒称精确重放':'The failure terminal has diagnostics but no complete restorable continuation. Inspect/export the trigger step, last valid state and inputs; exact replay is unavailable.',
  '研究完成，但部分成果未写入浏览器；请先导出完整结果与整库。':'Research completed, but some work is not persisted in this browser. Export full results and the complete archive.',
  '原有存档已保护，新的结果只保留在本会话':'Original archive protected; new results remain in this session only',
  '旧存档只读隔离；原文未覆盖，新成果仅本会话 / 未保存':'Original archive is quarantined read-only; original bytes were not overwritten. New work is session-only / unsaved.',
  '另一页面已修改存档；未执行替换，请先导出当前成果并刷新':'Another page changed the archive. Replacement was not performed; export current work before refreshing.',
  '另一页面已修改存档；未执行清空，请导出并刷新':'Another page changed the archive. Clear was not performed; export before refreshing.',
  '达到存档容量上限；旧存档未覆盖，新增成果仅本会话 / 未保存':'Archive capacity reached. Existing data was not overwritten; new work is session-only / unsaved.',
  '请求范围：滚转 ±360°/s，俯仰 ±120°/s，偏航 ±100°/s。连续积分参考；实际有效请求另受控制器速率上限约束。阶段结束后捕获实际达到的姿态。倒置时可能无法持续悬停。':'Request range: roll ±360°/s, pitch ±120°/s, yaw ±100°/s. References integrate continuously; the effective request is additionally capped by controller rate settings. The attained attitude is captured after the stage. Sustained inverted hover may be infeasible.',
  '受控比较：只有声明的控制器差异。':'Controlled comparison: only declared controller differences.',
  '描述性比较：初态 / 模型 / 风 / 气源 / 任务条件未全部匹配，不判定哪组更好。':'Descriptive comparison: initial state / model / wind / supply / task conditions do not all match. No better/worse verdict.',
  '超调沿目标方向投影。新版主统计来自全部 120 Hz 物理步；20 Hz 曲线及历史抽稀仅供显示。每条结果的 statisticsHz 独立保留。':'Overshoot is projected along the target direction. New primary statistics use all 120 Hz physical steps; 20 Hz and historical decimated curves are for display. Each result retains its own statisticsHz.',
},[
  [/^已完成 (\d+) \/ (\d+) · 部分成果仅保留在本会话，请导出全部记录。$/,(_,count,total)=>'Completed '+count+' / '+total+' · Some work remains in this session only; export all records.'],
  [/^现场记录：仅本会话 \/ 未保存。(.+)。可导出当前完整结果与整库；完成状态不表示已保存。$/,(_,reason)=>'Live records: session only / unsaved. '+t(reason)+'. Export the full result or archive; execution completion does not mean persisted.'],
  [/^(流程配置|流程结果)：仅本会话 \/ 未保存。(.+)$/,(_,kind,reason)=>t(kind)+': session only / unsaved. '+t(reason)],
  [/^仅本会话 \/ 未保存：(.+)。执行完成与物理结果不等于已保存；当前完整结果与整库均可导出。$/,(_,reason)=>'Session only / unsaved: '+t(reason)+'. Execution and physical outcome are separate from persistence; export current full results or the full archive.'],
  [/^本地流程已只读隔离：(.+)$/,(_,reason)=>'Original procedure archive quarantined read-only: '+t(reason)],
  [/^旧流程结果只读隔离：(.+)$/,(_,reason)=>'Original procedure results quarantined read-only: '+t(reason)],
  [/^旧存档只读隔离，未覆盖：(.+)$/,(_,reason)=>'Original archive quarantined read-only, not overwritten: '+t(reason)],
  [/^(执行日志|待运行配置)：(.+)$/,(_,kind,reason)=>t(kind)+': '+t(reason)],
  [/^(.+)。请导出全部记录 JSON 后再清理。$/,(_,reason)=>t(reason)+'. Export all records as JSON before cleanup.'],
  [/^实验室工作区 X ±24 \/ Z ±42 m，净高 24.1 m。(目标及车体包络可能越出工作区 \/ 净高；请求未被夹紧。)? (恒压外供气|有限车载气源) · (.+)$/,(_,warning,gas,authority)=>'Lab working area X ±24 / Z ±42 m; clear height 24.1 m. '+(warning?'Target and vehicle envelope may exceed it; the request was not clamped. ':'')+(gas==='恒压外供气'?'External constant-pressure supply':'Finite onboard gas')+' · '+t(authority)],
  [/^城市现场：世界高度不等于恢复净空。 (恒压外供气|有限车载气源) · (.+)$/,(_,gas,authority)=>'City: world height is not available recovery clearance. '+(gas==='恒压外供气'?'External constant-pressure supply':'Finite onboard gas')+' · '+t(authority)],
]);
